
const platforms=[['TikTok','Hook-first, casual'],['Instagram','Polished + hashtags'],['YouTube Shorts','Searchable title'],['Pinterest','Evergreen description'],['Threads','Conversation starter'],['X','Compact version']];
const defaults={posts:[],goals:[],analytics:[],commissions:[],money:[],events:[],vault:[],ideas:[],tagSets:[],inspirations:[],ignacioPlans:[],ignacioExperiments:[],promotionCampaigns:[],streamPlans:[],streamSessions:[],characters:[],products:[],backlog:[],packing:[{id:1,text:'Tablecloth',done:false},{id:2,text:'Price signs',done:false},{id:3,text:'Card reader and charger',done:false},{id:4,text:'Cash and change',done:false},{id:5,text:'Bags and sleeves',done:false},{id:6,text:'Tape, clips, and scissors',done:false}],timeline:[],preferences:{night:false,roomMood:'clear',roomPet:'🐈 Cat',onboarded:false,name:'Za',mainGoal:'Grow my art account',ignatzEnergy:'normal',incomeGoal:500,offerPrice:75,offerType:'Portrait commissions'}};
let currentPhoto='';
function normalizeState(raw){let s;try{s=Object.assign({},defaults,raw||{})}catch(e){s={...defaults}};for(const k in defaults){if(Array.isArray(defaults[k])&&!Array.isArray(s[k]))s[k]=[];if(!Array.isArray(defaults[k])&&(!s[k]||typeof s[k]!=='object'))s[k]=JSON.parse(JSON.stringify(defaults[k]))}return s}
let state;try{state=normalizeState(JSON.parse(localStorage.getItem('studioManagerData')||'{}'))}catch(e){state={...defaults}}
if(!state.backlog.length)state.backlog=[{id:101,title:'Relationship map for Character Vault',priority:'Should',status:'Next',notes:'Visual connections between characters.'},{id:102,title:'Customizable studio room',priority:'Nice',status:'Ideas',notes:'Furniture, pets, art on walls, and seasonal decor.'},{id:103,title:'Cloud sync and accounts',priority:'Future',status:'Ideas',notes:'Needed before a public app release.'},{id:104,title:'Artist Row inventory and pricing',priority:'Must',status:'Done',notes:'Added in v2.1.'},{id:105,title:'Inspiration pattern recognition',priority:'Should',status:'Done',notes:'Tag-based pattern summaries.'}];
const $=id=>document.getElementById(id),esc=s=>String(s||'').replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[m])),money=n=>Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD'}),today=()=>new Date().toISOString().slice(0,10);
function save(){try{localStorage.setItem('studioManagerData',JSON.stringify(state))}catch(e){alert('Studio Manager is almost out of storage space, so this change was not saved to your device. Try removing a few large photos (Characters, Composer, or Inspiration Garden), or export a backup from Settings and clear old data.')}renderAll()}
function openView(v){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===v));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===v))}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>openView(b.dataset.view)));
$('platformChecks').innerHTML=platforms.map(([p,d],i)=>`<label class="platform"><span class="checkline"><input type="checkbox" value="${p}" ${i<3?'checked':''}><strong>${p}</strong></span><span class="small muted">${d}</span></label>`).join('');
$('analyticsPlatform').innerHTML=platforms.map(p=>`<option>${p[0]}</option>`).join('');$('moneyDate').value=today();
function getPost(){return{id:Date.now(),title:$('postTitle').value.trim()||'Untitled post',caption:$('caption').value.trim(),hashtags:$('hashtags').value.trim(),date:$('scheduleDate').value,type:$('contentType').value,platforms:[...document.querySelectorAll('#platformChecks input:checked')].map(x=>x.value),mediaNote:$('mediaNote').value.trim(),photo:currentPhoto,photoSubject:$('photoSubject').value.trim(),photoProject:$('photoProject').value.trim(),status:'draft',created:new Date().toISOString()}}
function version(p,x){let c=x.caption||'';if(p==='TikTok')return `${c}\n\nWhat detail did you notice first?\n${x.hashtags}`.trim();if(p==='Instagram')return `${c}\n\n${x.hashtags}`.trim();if(p==='YouTube Shorts')return `${x.title}\n\n${c}\n\n${x.hashtags}`.trim();if(p==='Pinterest')return `${x.title}\n\n${c}\n\nDigital art inspiration, character design, and creative process.`.trim();if(p==='Threads')return `${c}\n\nArtists: what would you change or add?`.trim();return `${c} ${x.hashtags}`.slice(0,280).trim()}
function url(p){return{'TikTok':'https://www.tiktok.com/upload','Instagram':'https://www.instagram.com/','YouTube Shorts':'https://studio.youtube.com/','Pinterest':'https://www.pinterest.com/pin-creation-tool/','Threads':'https://www.threads.net/','X':'https://x.com/compose/post'}[p]||'#'}
function copyText(t,b){navigator.clipboard?.writeText(t).then(()=>{b.textContent='Copied!';setTimeout(()=>b.textContent='Copy',1000)}).catch(()=>prompt('Copy this text:',t))}
function showVersions(x){$('versions').innerHTML=x.platforms.length?x.platforms.map(p=>`<div class="item"><div class="item-head"><strong>${p}</strong><button class="btn ghost copy" data-text="${encodeURIComponent(version(p,x))}">Copy</button></div><p style="white-space:pre-wrap">${esc(version(p,x))}</p><a class="btn secondary" target="_blank" rel="noopener" style="text-decoration:none;display:inline-block" href="${url(p)}">Open ${p}</a></div>`).join(''):'<div class="empty">Choose a platform.</div>';$('versions').querySelectorAll('.copy').forEach(b=>b.addEventListener('click',()=>copyText(decodeURIComponent(b.dataset.text),b)))}
$('generateVersions').addEventListener('click',()=>showVersions(getPost()));$('savePost').addEventListener('click',()=>{const x=getPost();state.posts.unshift(x);save();showVersions(x);alert('Saved to your Post Library.')});
function setPhotoPreview(src){currentPhoto=src||'';$('photoPreview').src=currentPhoto;$('photoPreview').classList.toggle('hidden',!currentPhoto);$('removePhoto').classList.toggle('hidden',!currentPhoto)}
$('postPhoto').addEventListener('change',()=>{const f=$('postPhoto').files[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const max=1000,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);setPhotoPreview(c.toDataURL('image/jpeg',.82))};img.src=reader.result};reader.readAsDataURL(f)});
$('removePhoto').addEventListener('click',()=>{$('postPhoto').value='';setPhotoPreview('')});
function photoPostPackage(){const subject=$('photoSubject').value.trim()||'this new piece',project=$('photoProject').value.trim(),style=$('photoPostStyle').value,tone=$('photoTone').value;const projectText=project?` for ${project}`:'';let caption='';if(style==='Artwork reveal')caption=`I finally finished ${subject}${projectText}! I had so much fun bringing this idea to life, especially the details and expression. What catches your eye first?`;if(style==='Process and behind-the-scenes')caption=`A little behind-the-scenes look at ${subject}${projectText}. This piece changed a lot between the first sketch and the final version, and I love where it ended up. Which stage of the process do you enjoy seeing most?`;if(style==='Character story')caption=`Meet ${subject}${projectText}. I wanted this piece to show more than the design—I wanted the pose, expression, and atmosphere to hint at who they are. What kind of story do you imagine for them?`;if(style==='Engagement question')caption=`I made ${subject}${projectText} and now I need your opinion: what should I draw next—another scene, a different outfit, or a close-up portrait?`;if(style==='Portfolio showcase')caption=`New portfolio piece: ${subject}${projectText}. My focus was creating a clear mood, strong silhouette, and a polished finish while keeping the character's personality at the center.`;if(style==='Commission promotion')caption=`Commission example: ${subject}${projectText}. I love creating expressive character artwork with personal details and storytelling. Commission information is available—feel free to ask about current openings.`;if(tone==='Casual and funny')caption=caption.replace('I finally finished','Okay, I finally finished').replace('I made','So I made')+' ✨';if(tone==='Thoughtful and artistic')caption=caption.replace('I had so much fun','I focused on mood, storytelling, and').replace('What catches your eye first?','I would love to know what feeling it gives you.');if(tone==='Confident and professional')caption=caption.replace('I had so much fun bringing this idea to life','This piece was developed with close attention to composition, expression, and finish').replace('I need your opinion','I would love your feedback');if(tone==='Short and punchy')caption=`${subject}${projectText} ✨\n\n${style==='Process and behind-the-scenes'?'Sketch to final—what part is your favorite?':'What catches your eye first?'}`;const words=(subject+' '+project).toLowerCase(),tags=['#art','#digitalart','#artistsoftiktok','#artwork'];if(words.includes('oc')||words.includes('original'))tags.push('#originalcharacter','#ocart');if(words.includes('my hero')||words.includes('mha'))tags.push('#mhaoc','#myheroacademia');if(words.includes('fanart'))tags.push('#fanart');if(style.includes('Process'))tags.push('#artprocess','#speedpaint');if(style.includes('Commission'))tags.push('#artcommissions','#commissionsopen');$('caption').value=caption;$('hashtags').value=[...new Set(tags)].join(' ');$('postTitle').value=subject.charAt(0).toUpperCase()+subject.slice(1);$('mediaNote').value=currentPhoto?'Use uploaded artwork; check the crop and keep the focal point centered.':'Add the artwork before posting.';showVersions(getPost())}
$('createFromPhoto').addEventListener('click',photoPostPackage);

