$('captionProcess').addEventListener('click',()=>{$('caption').value=`From rough sketch to finished piece ✨\n\n${$('caption').value}\n\nI changed a few things along the way, but that is part of the fun.`.trim()});
$('applyHashtags').addEventListener('click',()=>{const s=state.tagSets.find(x=>String(x.id)==$('hashtagSetSelect').value);if(s)$('hashtags').value=s.tags});
$('buildThread').addEventListener('click',()=>{const parts=$('threadText').value.split(/\n\s*\n/).filter(Boolean);$('threadOutput').innerHTML=parts.length?parts.map((p,i)=>`<div class="item"><strong>${i+1}/${parts.length}</strong><p>${esc(p)}</p><button class="btn ghost threadCopy" data-text="${encodeURIComponent(p)}">Copy</button></div>`).join(''):'<div class="empty">Add text separated by blank lines.</div>';$('threadOutput').querySelectorAll('.threadCopy').forEach(b=>b.addEventListener('click',()=>copyText(decodeURIComponent(b.dataset.text),b)))});
function cover(){const h=$('coverHook').value.trim(),f=$('coverFocus').value.trim();$('coverPreview').innerHTML=h?`<strong>${esc(h)}</strong><br><span class="muted">${esc($('coverFormat').value)} • Keep the main subject centered and text away from the top/bottom interface areas.${f?' Focus: '+esc(f):''}</span>`:'Add a hook to preview your cover plan.'}['coverHook','coverFocus','coverFormat'].forEach(id=>$(id).addEventListener('input',cover));
$('postFilter').addEventListener('change',renderPosts);$('postSearch').addEventListener('input',renderPosts);
function renderPosts(){let a=state.posts;if($('postFilter').value!=='all')a=a.filter(x=>x.status===$('postFilter').value);const q=$('postSearch').value.toLowerCase();a=a.filter(x=>(x.title+' '+x.caption+' '+x.type).toLowerCase().includes(q));$('postLibrary').innerHTML=a.length?a.map(x=>`<div class="item"><div class="item-head"><div><strong>${esc(x.title)}</strong><div class="small muted">${esc(x.type)}${x.date?' • '+x.date:''} • ${esc((x.platforms||[]).join(', '))}</div></div><span class="badge">${x.status}</span></div>${x.photo?`<img class="photo-thumb" src="${x.photo}" alt="Artwork for ${esc(x.title)}">`:''}<p>${esc(x.caption).slice(0,200)}</p>${x.mediaNote?`<p class="small muted">Cover: ${esc(x.mediaNote)}</p>`:''}<div class="row"><button class="btn secondary viewVersions" data-id="${x.id}">Versions</button>${x.status!=='posted'?`<button class="btn good markPosted" data-id="${x.id}">Mark posted</button>`:''}<button class="btn danger deletePost" data-id="${x.id}">Delete</button></div></div>`).join(''):'<div class="empty">No matching posts.</div>';$('postLibrary').querySelectorAll('.viewVersions').forEach(b=>b.addEventListener('click',()=>{openView('composer');showVersions(state.posts.find(x=>x.id==b.dataset.id))}));$('postLibrary').querySelectorAll('.markPosted').forEach(b=>b.addEventListener('click',()=>{const x=state.posts.find(p=>p.id==b.dataset.id);x.status='posted';x.postedDate=today();state.goals.filter(g=>g.type==='posts').forEach(g=>g.current=Math.min(g.target,Number(g.current)+1));save()}));$('postLibrary').querySelectorAll('.deletePost').forEach(b=>b.addEventListener('click',()=>{if(confirm('Delete this post?')){state.posts=state.posts.filter(x=>x.id!=b.dataset.id);save()}}))}
function renderCalendar(){const s=new Date(),out=[];for(let i=0;i<14;i++){const d=new Date(s);d.setDate(s.getDate()+i);const iso=d.toISOString().slice(0,10),ps=state.posts.filter(x=>x.date===iso);out.push(`<div class="day"><strong>${d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</strong>${ps.map(x=>`<span class="dot">${esc(x.title)}</span>`).join('')}</div>`)}$('calendarGrid').innerHTML=out.join('')}
$('saveAnalytics').addEventListener('click',()=>{if(!$('analyticsPost').value)return alert('Create a post first.');state.analytics.unshift({id:Date.now(),postId:Number($('analyticsPost').value),platform:$('analyticsPlatform').value,views:Number($('aViews').value||0),likes:Number($('aLikes').value||0),comments:Number($('aComments').value||0),shares:Number($('aShares').value||0),followers:Number($('aFollowers').value||0),date:today()});const f=Number($('aFollowers').value||0);state.goals.filter(g=>g.type==='followers'&&f).forEach(g=>g.current=Math.max(g.current,f));save()});
function renderAnalytics(){ $('analyticsPost').innerHTML=state.posts.length?state.posts.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join(''):'<option value="">No posts yet</option>';const a=state.analytics,totalViews=a.reduce((s,x)=>s+x.views,0),eng=a.reduce((s,x)=>s+x.likes+x.comments+x.shares,0),rate=totalViews?eng/totalViews*100:0;const by={};a.forEach(x=>{const p=state.posts.find(y=>y.id===x.postId);if(!p)return;const k=p.type;by[k]??={views:0,eng:0,n:0};by[k].views+=x.views;by[k].eng+=x.likes+x.comments+x.shares;by[k].n++});const best=Object.entries(by).sort((a,b)=>b[1].views-a[1].views)[0];$('analyticsSummary').innerHTML=`<div class="grid"><div class="span-4"><div class="muted">Tracked views</div><div class="metric">${totalViews.toLocaleString()}</div></div><div class="span-4"><div class="muted">Interactions</div><div class="metric">${eng.toLocaleString()}</div></div><div class="span-4"><div class="muted">Engagement</div><div class="metric">${rate.toFixed(1)}%</div></div></div><div class="notice" style="margin-top:12px">${best?`Your most-viewed tracked format is <strong>${esc(best[0])}</strong>. This is based only on results you entered.`:'Add performance results to discover which formats work best.'}</div>`;$('analyticsLog').innerHTML=a.length?`<table class="stat-table"><thead><tr><th>Post</th><th>Platform</th><th>Views</th><th>Likes</th><th>Comments</th><th>Shares</th><th></th></tr></thead><tbody>${a.map(x=>{const p=state.posts.find(y=>y.id===x.postId);return`<tr><td>${esc(p?.title||'Deleted post')}</td><td>${x.platform}</td><td>${x.views}</td><td>${x.likes}</td><td>${x.comments}</td><td>${x.shares}</td><td><button class="btn danger delAnalytics" data-id="${x.id}">×</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No performance results yet.</div>';$('analyticsLog').querySelectorAll('.delAnalytics').forEach(b=>b.addEventListener('click',()=>{state.analytics=state.analytics.filter(x=>x.id!=b.dataset.id);save()}))}
$('addGoal').addEventListener('click',()=>{if(!$('goalName').value.trim()||Number($('goalTarget').value)<1)return alert('Add a name and target.');state.goals.push({id:Date.now(),name:$('goalName').value.trim(),type:$('goalType').value,current:Number($('goalCurrent').value),target:Number($('goalTarget').value)});$('goalName').value='';save()});
function renderGoals(){const e=$('goalList');e.innerHTML=state.goals.length?state.goals.map(g=>{const p=Math.min(100,Math.round(g.current/g.target*100));return`<div class="item"><div class="item-head"><strong>${esc(g.name)}</strong><span>${g.type==='revenue'?money(g.current):g.current} / ${g.type==='revenue'?money(g.target):g.target}</span></div><div class="progress"><span style="width:${p}%"></span></div><div class="row"><button class="btn secondary goalAdj" data-id="${g.id}" data-d="1">+1</button><button class="btn ghost goalAdj" data-id="${g.id}" data-d="-1">-1</button><button class="btn danger goalDel" data-id="${g.id}">Delete</button></div></div>`}).join(''):'<div class="empty">No goals yet.</div>';e.querySelectorAll('.goalAdj').forEach(b=>b.addEventListener('click',()=>{const g=state.goals.find(x=>x.id==b.dataset.id);g.current=Math.max(0,Math.min(g.target,Number(g.current)+Number(b.dataset.d)));save()}));e.querySelectorAll('.goalDel').forEach(b=>b.addEventListener('click',()=>{state.goals=state.goals.filter(x=>x.id!=b.dataset.id);save()}))}
$('addCommission').addEventListener('click',()=>{if(!$('clientName').value.trim()||!$('commissionTitle').value.trim())return alert('Add the client and project.');state.commissions.unshift({id:Date.now(),client:$('clientName').value.trim(),title:$('commissionTitle').value.trim(),price:Number($('commissionPrice').value||0),due:$('commissionDue').value,status:$('commissionStatus').value,notes:$('commissionNotes').value.trim()});save()});
const stages=['Inquiry','Awaiting payment','Sketch','Approval','Rendering','Delivered'];function renderCommissions(){$('commissionBoard').innerHTML=stages.slice(0,4).map(s=>`<div class="lane"><h3>${s}</h3>${state.commissions.filter(x=>x.status===s).map(x=>`<div class="item"><strong>${esc(x.title)}</strong><div class="small">${esc(x.client)} • ${money(x.price)}</div><select class="commissionMove" data-id="${x.id}">${stages.map(z=>`<option ${z===x.status?'selected':''}>${z}</option>`).join('')}</select></div>`).join('')||'<div class="small muted">Empty</div>'}</div>`).join('');document.querySelectorAll('.commissionMove').forEach(s=>s.addEventListener('change',()=>{state.commissions.find(x=>x.id==s.dataset.id).status=s.value;save()}));$('invoiceSelect').innerHTML=state.commissions.length?state.commissions.map(x=>`<option value="${x.id}">${esc(x.client)} — ${esc(x.title)}</option>`).join(''):'<option value="">No commissions</option>';renderInvoice()}
function renderInvoice(){const x=state.commissions.find(c=>c.id==$('invoiceSelect').value)||state.commissions[0];$('invoicePreview').innerHTML=x?`<div class="invoice print-area"><div class="item-head"><div><h2>Studio Manager Invoice</h2><div>Artist services</div></div><div class="right"><strong>Invoice #${String(x.id).slice(-6)}</strong><div>${today()}</div></div></div><hr><p><strong>Bill to:</strong> ${esc(x.client)}</p><table class="stat-table"><tr><th>Service</th><th class="right">Amount</th></tr><tr><td>${esc(x.title)}</td><td class="right">${money(x.price)}</td></tr><tr><th>Total</th><th class="right">${money(x.price)}</th></tr></table><p class="small">Due: ${x.due||'Upon receipt'}<br>${esc(x.notes||'Thank you for supporting independent art.')}</p><button class="btn no-print" onclick="window.print()">Print / Save PDF</button></div>`:'<div class="empty">Add a commission to create an invoice.</div>'}$('invoiceSelect').addEventListener('change',renderInvoice);
$('addMoney').addEventListener('click',()=>{if(!$('moneyDesc').value.trim()||Number($('moneyAmount').value)<=0)return alert('Add a description and amount.');const x={id:Date.now(),type:$('moneyType').value,description:$('moneyDesc').value.trim(),amount:Number($('moneyAmount').value),date:$('moneyDate').value||today(),category:$('moneyCategory').value};state.money.unshift(x);if(x.type==='income')state.goals.filter(g=>g.type==='revenue').forEach(g=>g.current=Math.min(g.target,Number(g.current)+x.amount));save()});
