function renderBusiness(){const inc=state.money.filter(x=>x.type==='income').reduce((s,x)=>s+x.amount,0),exp=state.money.filter(x=>x.type==='expense').reduce((s,x)=>s+x.amount,0);$('businessSummary').innerHTML=`<div class="grid"><div class="span-4"><div class="muted">Income</div><div class="metric">${money(inc)}</div></div><div class="span-4"><div class="muted">Expenses</div><div class="metric">${money(exp)}</div></div><div class="span-4"><div class="muted">Net</div><div class="metric">${money(inc-exp)}</div></div></div><p class="small muted">This is an organizer, not tax advice. Keep receipts and verify deductible expenses with a tax professional.</p>`;$('moneyLog').innerHTML=state.money.length?state.money.map(x=>`<div class="item"><div class="item-head"><div><strong>${esc(x.description)}</strong><div class="small muted">${x.date} • ${esc(x.category)}</div></div><strong>${x.type==='expense'?'-':'+'}${money(x.amount)}</strong></div><button class="btn danger delMoney" data-id="${x.id}">Delete</button></div>`).join(''):'<div class="empty">No transactions yet.</div>';$('moneyLog').querySelectorAll('.delMoney').forEach(b=>b.addEventListener('click',()=>{state.money=state.money.filter(x=>x.id!=b.dataset.id);save()}));$('eventList').innerHTML=state.events.length?state.events.map(x=>`<div class="item"><div class="item-head"><strong>${esc(x.name)}</strong><span>${x.date||'No date'}</span></div><div class="small">Fee: ${money(x.fee)}</div><p>${esc(x.notes)}</p><button class="btn danger delEvent" data-id="${x.id}">Delete</button></div>`).join(''):'<div class="empty">No events planned.</div>';$('eventList').querySelectorAll('.delEvent').forEach(b=>b.addEventListener('click',()=>{state.events=state.events.filter(x=>x.id!=b.dataset.id);save()}))}
$('addVault').addEventListener('click',()=>{if(!$('vaultName').value.trim())return;state.vault.unshift({id:Date.now(),name:$('vaultName').value.trim(),category:$('vaultCategory').value,world:$('vaultWorld').value.trim(),colors:$('vaultColors').value.split(',').map(x=>x.trim()).filter(Boolean),notes:$('vaultNotes').value.trim()});save()});$('vaultSearch').addEventListener('input',renderVault);
function renderVault(){const q=$('vaultSearch').value.toLowerCase(),a=state.vault.filter(x=>(x.name+' '+x.category+' '+x.world+' '+x.notes).toLowerCase().includes(q));$('vaultList').innerHTML=a.length?a.map(x=>`<div class="item"><div class="item-head"><div><strong>${esc(x.name)}</strong><div class="small muted">${esc(x.category)}${x.world?' • '+esc(x.world):''}</div></div><button class="btn danger delVault" data-id="${x.id}">Delete</button></div><p>${esc(x.notes)}</p><div class="swatches">${x.colors.map(c=>`<div class="swatch" style="background:${/^#[0-9a-f]{6}$/i.test(c)?c:'#ddd'}"><span>${esc(c)}</span></div>`).join('')}</div></div>`).join(''):'<div class="empty">Your character and project references will live here.</div>';$('vaultList').querySelectorAll('.delVault').forEach(b=>b.addEventListener('click',()=>{state.vault=state.vault.filter(x=>x.id!=b.dataset.id);save()}))}
