function generateIgnatzPlan(){const f=$('igFocus').value,g=$('igGoal').value,e=$('igEffort').value,r=a=>a[Math.floor(Math.random()*a.length)],title=r(igIdeas[f]),cta={Views:'Would this make you stop scrolling?',Comments:'Pick A or B and tell me why.',Followers:'Follow for the next piece in this series.',Saves:'Save this for your next art session.',Sales:'Would you want this as a print, sticker, or bookmark?'}[g];currentIgnatzPlan={id:Date.now(),title,focus:f,goal:g,effort:e,hook:r(igHooks),shots:igShots[e],cta,date:'',format:'Generated plan',done:false};$('igIdeaOutput').innerHTML=`<strong>${esc(title)}</strong><p><b>Hook:</b> ${esc(currentIgnatzPlan.hook)}</p><p><b>Shot list:</b> ${currentIgnatzPlan.shots.map(esc).join(' → ')}</p><p><b>CTA:</b> ${esc(cta)}</p>`}
function renderIgnatz(){
 const tracked=state.analytics.length,views=state.analytics.reduce((s,x)=>s+(+x.views||0),0),avg=tracked?Math.round(views/tracked):0,postedIds=new Set(state.analytics.map(x=>String(x.postId))),unused=state.posts.filter(x=>!postedIds.has(String(x.id))).length;
 $('igPosts').textContent=tracked;$('igViews').textContent=avg.toLocaleString();$('igUnused').textContent=unused;
 const groups={};state.analytics.forEach(a=>{const p=state.posts.find(x=>String(x.id)===String(a.postId)),k=p?.type||p?.platform||a.platform||'Post';groups[k]??={v:0,n:0};groups[k].v+=+a.views||0;groups[k].n++});const best=Object.entries(groups).sort((a,b)=>b[1].v/b[1].n-a[1].v/a[1].n)[0];$('igBest').textContent=best?best[0]:'—';
 const notes=[];if(!state.posts.length)notes.push('Create or import a few posts so I can start connecting your artwork to content.');if(state.inspirations.length>=3)notes.push(`You have ${state.inspirations.length} saved inspirations. Turn one repeated mood or subject into a three-post mini-series.`);if(unused>0)notes.push(`${unused} saved post${unused===1?' has':'s have'} no performance record yet. Log results or repurpose the strongest piece.`);if(tracked>=3)notes.push(`Your tracked posts average ${avg.toLocaleString()} views. Repeat the structure of the best one before changing every variable.`);if(!notes.length)notes.push('Start small today: choose one finished piece and make a reveal, a detail crop, and a story post.');$('ignacioBrief').textContent=notes[0];$('ignacioChips').innerHTML=notes.slice(1).map(n=>`<span class="status-chip">✨ ${esc(n)}</span>`).join('');
 $('igPlanner').innerHTML=state.ignacioPlans.length?state.ignacioPlans.map(x=>`<div class="item"><div class="item-head"><div><strong style="${x.done?'text-decoration:line-through;opacity:.55':''}">${esc(x.title)}</strong><div class="small muted">${esc(x.format)} • ${x.date||'Unscheduled'}</div></div><div><button class="btn secondary igDone" data-id="${x.id}">${x.done?'Undo':'Done'}</button> <button class="btn danger igDelete" data-id="${x.id}">Delete</button></div></div></div>`).join(''):'<div class="empty">No planned content yet.</div>';
 $('igPlanner').querySelectorAll('.igDone').forEach(b=>b.onclick=()=>{const x=state.ignacioPlans.find(y=>String(y.id)===b.dataset.id);if(x)x.done=!x.done;save()});$('igPlanner').querySelectorAll('.igDelete').forEach(b=>b.onclick=()=>{state.ignacioPlans=state.ignacioPlans.filter(x=>String(x.id)!==b.dataset.id);save()});
 $('igExperiments').innerHTML=state.ignacioExperiments.length?state.ignacioExperiments.map(x=>`<div class="item"><strong>${esc(x.test)}</strong><div class="small muted">Measure: ${esc(x.metric)}</div><button class="btn danger igExpDelete" data-id="${x.id}" style="margin-top:7px">Delete</button></div>`).join(''):'<div class="empty">Test one variable at a time.</div>';$('igExperiments').querySelectorAll('.igExpDelete').forEach(b=>b.onclick=()=>{state.ignacioExperiments=state.ignacioExperiments.filter(x=>String(x.id)!==b.dataset.id);save()});
}
