document.querySelectorAll('[data-igaction]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.igaction;if(a==='idea'){generateIgnatzPlan();$('ignacioActionResult').innerHTML=$('igIdeaOutput').innerHTML}else if(a==='repurpose'){$('ignacioActionResult').textContent='Choose a finished artwork below. I will turn it into six distinct posts.'}else if(a==='promotion'){document.getElementById('promoItem').focus();$('ignacioActionResult').textContent='Build one focused campaign below. Use a small test budget and define the result that would make the promotion worthwhile.'}else if(a==='income'){const products=state.products.filter(x=>x.stock>0),open=state.commissions.filter(x=>x.status!=='Delivered');$('ignacioActionResult').textContent=products.length?`Promote ${products[0].name} with a clear price, one close-up, and a deadline or stock count. Your goal is a real sale—not empty views.`:open.length?`Share one progress update from ${open[0].title}, then open one clearly priced commission slot similar to it.`:'Create one simple offer today: a clearly priced portrait slot, character design slot, digital download, or small product.'}else{const n=state.analytics.length;$('ignacioActionResult').textContent=n<3?'Log at least three post results before trusting a trend. Start by testing hooks and keeping the subject consistent.':`You have ${n} tracked results. Repeat the format with the strongest average views, then change only one variable.`}}));

let selectedEnergy=state.preferences.ignatzEnergy||'normal';
function syncEnergyButtons(){document.querySelectorAll('[data-energy]').forEach(b=>b.classList.toggle('active',b.dataset.energy===selectedEnergy))}
document.querySelectorAll('[data-energy]').forEach(b=>b.addEventListener('click',()=>{selectedEnergy=b.dataset.energy;state.preferences.ignatzEnergy=selectedEnergy;syncEnergyButtons();save()}));
function buildDailyRoutine(){const routines={low:[['🎨','Spend 10 minutes finishing the easiest existing sketch or draft.'],['📱','Post one simple reveal, detail crop, or older-art comparison.'],['💬','Reply thoughtfully to one real comment.']],normal:[['🎨','Make or finish one reusable piece of content.'],['📱','Post one hook-first video and save a second version as a draft.'],['💬','Reply to three real comments and leave two genuine comments in your niche.'],['📊','Log the result later so Ignatz can compare it.']],sprint:[['🎨','Batch one main artwork plus three close-up or process clips.'],['📱','Prepare three posts: discovery, connection, and offer.'],['💬','Spend 15 focused minutes on genuine community interaction.'],['💵','Promote one clearly priced product or commission offer.'],['📊','Record views, saves, comments, and followers gained.']]};$('igRoutine').innerHTML=routines[selectedEnergy].map(x=>`<div class="routine-step"><span>${x[0]}</span><span>${esc(x[1])}</span></div>`).join('')}
$('igBuildRoutine').addEventListener('click',buildDailyRoutine);
function calculateIncomeGoal(){const goal=Math.max(0,+$('igIncomeGoal').value||0),price=Math.max(1,+$('igOfferPrice').value||1),type=$('igOfferType').value,count=Math.ceil(goal/price),weekly=Math.ceil(count/4),current=state.money.filter(x=>x.type==='income'&&String(x.date||'').slice(0,7)===today().slice(0,7)).reduce((s,x)=>s+x.amount,0),left=Math.max(0,goal-current);state.preferences.incomeGoal=goal;state.preferences.offerPrice=price;state.preferences.offerType=type;$('igIncomeOutput').innerHTML=`<div class="income-grid"><div class="income-result"><span class="small muted">Sales needed</span><strong>${count}</strong></div><div class="income-result"><span class="small muted">Weekly target</span><strong>${weekly}</strong></div><div class="income-result"><span class="small muted">Still needed</span><strong>${money(left)}</strong></div></div><p><b>Best next move:</b> Open or promote ${count} ${esc(type.toLowerCase())} at about ${money(price)} each. Show one example, state the price plainly, limit the number of slots, and give people one clear way to buy or inquire.</p>`;save()}
