function timelineEntries(){
 const manual=(state.timeline||[]).map(x=>({...x,source:'manual'}));
 const posts=state.posts.map(x=>({id:'post'+x.id,title:(x.status==='posted'?'Published ':'Created draft: ')+x.title,type:'Post',date:(x.postedDate||x.date||x.created||'').slice(0,10),notes:x.type||'',source:'auto'}));
 const chars=state.characters.map(x=>({id:'char'+x.id,title:'Created character: '+x.name,type:'Character',date:(x.created||'').slice(0,10),notes:x.world||x.role||'',source:'auto'}));
 const sales=state.money.filter(x=>x.type==='income').map(x=>({id:'sale'+x.id,title:'Earned '+money(x.amount)+' — '+x.description,type:'Sale',date:x.date,notes:x.category||'',source:'auto'}));
 const events=state.events.map(x=>({id:'event'+x.id,title:'Event: '+x.name,type:'Event',date:x.date,notes:x.notes||'',source:'auto'}));
 return [...manual,...posts,...chars,...sales,...events].filter(x=>x.date).sort((a,b)=>String(b.date).localeCompare(String(a.date)));
}
