$('timelineDate').value=today();$('addTimeline').onclick=()=>{const title=$('timelineTitle').value.trim();if(!title)return alert('Add a milestone title.');state.timeline.unshift({id:Date.now(),title,type:$('timelineType').value,date:$('timelineDate').value||today(),notes:$('timelineNotes').value.trim()});$('timelineTitle').value='';$('timelineNotes').value='';save()};$('timelineFilter').onchange=renderTimeline;

