// v2.3 design-system helpers, Ignatz interactions, and living-room ambience
const APP_RELEASE={version:'3.0.0',name:'UI Refresh + Reliable Twitch Studio',released:'2026-08-02'};
window.StudioUI={
 card:(title,body,extra='')=>`<article class="component-card ${extra}"><h3>${esc(title)}</h3>${body}</article>`,
 badge:(text)=>`<span class="badge">${esc(text)}</span>`,
 empty:(text)=>`<div class="empty">${esc(text)}</div>`,
 button:(label,kind='secondary',attrs='')=>`<button class="btn ${kind}" ${attrs}>${esc(label)}</button>`
};
function migrateV23(){
 state.preferences=state.preferences||{}; if(!state.preferences.ignatzMood)state.preferences.ignatzMood='calm';
 const needsWrite=!state.meta||state.meta.lastVersion!==APP_RELEASE.version;
 state.meta=state.meta||{}; state.meta.lastVersion=APP_RELEASE.version; state.meta.updatedAt=new Date().toISOString();
 if(needsWrite)try{localStorage.setItem('studioManagerData',JSON.stringify(state))}catch(e){}
}
function addRoomAmbience(){
 const room=$('studioRoom'); if(!room||room.querySelector('.room-ambient'))return;
 [['room-sunbeam',''],['room-dust',''],['room-clock','🕰️'],['room-steam','♨'],['room-plant','🪴'],['room-lights','✦ ✦ ✦ ✦ ✦']].forEach(([c,t])=>{const el=document.createElement('span');el.className='room-ambient '+c;el.textContent=t;room.prepend(el)});
}
function setIgnatzMood(mood='calm'){
 const avatar=$('ignatzAvatar'); if(!avatar)return; avatar.classList.remove('thinking','proud','sleepy','excited');
 if(mood!=='calm')avatar.classList.add(mood); state.preferences.ignatzMood=mood;
}
function speakAsIgnatz(message,mood='calm'){
 setIgnatzMood(mood); const target=$('ignacioActionResult')||$('roomFocus'); if(target)target.textContent=message;
 setTimeout(()=>setIgnatzMood('calm'),2600);
}
function updateIgnatzByTime(){
 const h=new Date().getHours(); const mood=h>=22||h<6?'sleepy':state.posts.some(x=>x.status==='posted')?'proud':'calm'; setIgnatzMood(mood);
 const greeting=h<12?'Good morning':h<18?'Good afternoon':'Good evening';
 const hero=document.querySelector('.ignacio-hero h2'); if(hero)hero.textContent=`${greeting}, ${state.preferences.name||'Za'}. I’m Ignatz.`;
}
function enhanceNativeNavigation(){
 const dock=document.querySelector('.mobile-dock'); if(!dock)return;
 document.querySelectorAll('.mobile-dock button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.mobile-dock button').forEach(x=>x.removeAttribute('data-active'));btn.setAttribute('data-active','true');if(navigator.vibrate)navigator.vibrate(8)}));
}
function installIgnatzInteractions(){
 const avatar=$('ignatzAvatar'); if(avatar)avatar.addEventListener('click',()=>{const notes=[['I’m here. Let’s make the next step small and specific.','thinking'],['You do not need a perfect plan—just a useful next action.','proud'],['One finished piece can become several strong posts.','excited']];const [moodText,mood]=notes[Math.floor(Math.random()*notes.length)];speakAsIgnatz(moodText,mood)});
 const daily=$('ignacioDaily'); if(daily)daily.addEventListener('click',()=>setTimeout(()=>setIgnatzMood('thinking'),20));
}
function showReleaseInSettings(){
 const settings=$('settings'); if(!settings||settings.querySelector('.release-panel'))return;
 const panel=document.createElement('div');panel.className='card release-panel';panel.innerHTML=`<h2>About this release</h2><p><strong>Studio Manager ${APP_RELEASE.version}</strong> — ${APP_RELEASE.name}</p><p class="small muted">Expanded the organic Growth Lab with a seven-day sprint and upgraded the local editor with reordering, trim controls, crop modes, safe-zone previews, posting packs, and clearer export progress.</p>`;settings.prepend(panel);
}
