function buildOrganicPlan(){
 const subject=$('growthSubject').value.trim()||'this artwork',goal=$('growthGoal').value,style=$('growthStyle').value,audience=$('growthAudience').value.trim()||'people who enjoy art like yours',length=+$('growthLength').value,frame=+$('growthFrame').value;
 const hooks=growthHooks[style]||growthHooks['Fast reveal'],hook=hooks[Math.floor(Math.random()*hooks.length)];
 const scores={Hook:Math.min(100,58+frame*12),Visual:frame>=2?90:65,Readability:length<=15?84:72,Shareability:goal.includes('community')?88:74,Retention:Math.min(95,62+frame*10+(length<=15?8:0))};
 const overall=Math.round(Object.values(scores).reduce((a,b)=>a+b,0)/5);
 const cta=goal==='Sell commissions'?'Commission details are in my profile—send me your idea.':goal==='Sell a product'?'The finished piece is available through my profile.':goal==='Get comments and community'?'Which part should I show next?':goal==='Earn followers'?'Follow for the next character reveal.':'Save this if you want to see the next version.';
 const beats=length<=12?[['0–1s','Show the finished art or strongest close-up'],['1–4s','Jump back to sketch/process'],['4–8s','Show two satisfying changes'],[`${Math.max(8,length-3)}–${length}s`,'Full reveal + one CTA']]:[['0–1s','Finished result first'],['1–5s','Set up the problem or story'],['5–12s','Fast process beats'],[`12–${Math.max(15,length-4)}s`,'Details, emotion, or useful explanation'],[`${Math.max(15,length-4)}–${length}s`,'Reveal + CTA']];
 const caption=`${hook}\n\n${subject} for ${audience}. ${cta}`;
 growthStore.plans.unshift({id:Date.now(),subject,goal,style,hook,cta,overall,created:new Date().toISOString()});growthStore.plans=growthStore.plans.slice(0,20);saveGrowth();
 $('growthOutput').innerHTML=`<div class="promo-section growth-plan"><h3>Opening hook</h3><p id="organicHook"><b>${esc(hook)}</b></p><button class="btn ghost copyOrganic" data-copy="organicHook">Copy</button></div><div class="promo-section"><h3>Video timeline</h3>${beats.map(x=>`<div class="safety-check"><b>${x[0]}</b><span>${esc(x[1])}</span></div>`).join('')}</div><div class="promo-section"><h3>Caption</h3><p id="organicCaption" style="white-space:pre-wrap">${esc(caption)}</p><button class="btn ghost copyOrganic" data-copy="organicCaption">Copy</button></div><div class="promo-section"><h3>Ignatz’s fixes</h3><p>${frame<2?'Do not begin with a blank canvas. Put the strongest finished frame in the first second.':'Your first frame is strong enough to stop a scroll.'} ${length>15?'Cut pauses aggressively and give each section a visual change every 1–3 seconds.':'Keep the pace tight and remove any frame that does not add information.'}</p></div>`;
 $('viralScore').textContent=overall;$('viralScore').style.background=`conic-gradient(var(--accent) ${overall*3.6}deg,#eee 0)`;
 $('scoreBreakdown').innerHTML=Object.entries(scores).map(([k,v])=>`<div><div class="item-head"><span>${k}</span><b>${v}%</b></div><div class="score-bar"><span style="width:${v}%"></span></div></div>`).join('');
 const money=goal.includes('Sell')?88:goal==='Build recognition'?72:60;$('moneyScore').innerHTML=`<b>${money}/100</b> — ${money>80?'This post has a clear path to income because the offer and CTA are specific.':'This is primarily an audience-building post. Pair it with a follow-up that shows your commission offer, product, or portfolio.'}`;
 $('videoHook').value=hook;$('videoCTA').value=cta;$('videoLength').value=String([8,12,15,30].reduce((a,b)=>Math.abs(b-length)<Math.abs(a-length)?b:a));
 document.querySelectorAll('.copyOrganic').forEach(b=>b.onclick=()=>navigator.clipboard?.writeText($(b.dataset.copy).innerText));
 if($('packageCaption'))$('packageCaption').textContent=caption;if($('packageCover'))$('packageCover').textContent=hook;
}
$('growthBuild').onclick=buildOrganicPlan;
$('growthHooks').onclick=()=>{const style=$('growthStyle').value,hooks=growthHooks[style]||growthHooks['Fast reveal'];$('growthOutput').innerHTML=`<div class="promo-section"><h3>Hook options</h3>${hooks.concat(['I changed one thing and the whole piece finally worked.','Would you keep the sketch version or the final?']).map(h=>`<button class="hook-chip" type="button">${esc(h)}</button>`).join('')}</div>`;document.querySelectorAll('.hook-chip').forEach(b=>b.onclick=()=>{$('videoHook').value=b.textContent;$('growthSubject').focus()})};

function analyzeCreatorDNA(){
 const posts=state.posts||[];if(!posts.length){$('creatorDNA').innerHTML='<b>Not enough history yet.</b> Log at least three posts with views and formats. Ignatz will compare them without needing access to your TikTok password.';return}
 const groups={};posts.forEach(p=>{const key=p.format||p.platform||'Uncategorized';(groups[key]||(groups[key]=[])).push(+p.views||0)});const ranked=Object.entries(groups).map(([k,a])=>[k,Math.round(a.reduce((x,y)=>x+y,0)/a.length),a.length]).sort((a,b)=>b[1]-a[1]);const top=[...posts].sort((a,b)=>(+b.views||0)-(+a.views||0)).slice(0,3);
 $('creatorDNA').innerHTML=`<p><b>Strongest format:</b> ${esc(ranked[0]?.[0]||'Unknown')} (${(ranked[0]?.[1]||0).toLocaleString()} average views).</p><p><b>Top subjects:</b> ${top.map(x=>esc(x.title||x.topic||'Untitled')).join(', ')||'Add titles to your posts.'}</p><p class="small muted">Ignatz’s next experiment: repeat the strongest format with a new subject, then compare saves, comments, and followers—not views alone.</p>`;
}
$('refreshDNA').onclick=analyzeCreatorDNA;
function renderExperiments(){const a=growthStore.experiments;$('experimentList').innerHTML=a.length?a.map(x=>`<div class="item"><div class="item-head"><div><b>${esc(x.name)}</b><div class="small muted">${esc(x.variant)}</div></div><button class="btn danger expDel" data-id="${x.id}">×</button></div></div>`).join(''):'<div class="empty">No experiments saved yet.</div>';document.querySelectorAll('.expDel').forEach(b=>b.onclick=()=>{growthStore.experiments=growthStore.experiments.filter(x=>String(x.id)!==b.dataset.id);saveGrowth();renderExperiments()})}
$('saveExperiment').onclick=()=>{const name=$('experimentName').value.trim(),variant=$('experimentVariant').value.trim();if(!name)return alert('Name the test.');growthStore.experiments.unshift({id:Date.now(),name,variant,status:'Running'});saveGrowth();renderExperiments();$('experimentName').value='';$('experimentVariant').value=''};
function buildContentBank(){const unused=(state.vault||[]).slice(0,4),drafts=(state.posts||[]).filter(x=>x.status!=='posted').slice(0,3);const items=[...unused.map(x=>x.title||x.name||'Vault artwork'),...drafts.map(x=>x.title||'Draft post')];$('contentBank').innerHTML=items.length?`<b>${esc(items[0])}</b> can become: a final reveal, close-up detail, sketch comparison, character fact, color-palette post, funny persona reaction, and commission example.<div class="small muted" style="margin-top:8px">Also ready: ${items.slice(1).map(esc).join(', ')||'add more art to your vault.'}</div>`:'Add artwork to your Art Vault or save draft posts. Ignatz will surface pieces you have not fully reused.'}
