let previewPaused=false,previewTime=0;
function loadEditorFiles(files){editorClips.forEach(x=>URL.revokeObjectURL(x.url));editorClips=[...files].map((f,i)=>({id:Date.now()+i,file:f,url:URL.createObjectURL(f),type:f.type.startsWith('video')?'video':'image',duration:0,start:0,end:0,trimStart:0,sourceDuration:0}));setupEditorPlan();}
$('videoFiles').onchange=e=>loadEditorFiles(e.target.files);
async function probeClip(c){if(c.type!=='video')return c;const v=document.createElement('video');v.preload='metadata';v.src=c.url;await new Promise(r=>{v.onloadedmetadata=r;v.onerror=r});c.sourceDuration=isFinite(v.duration)?v.duration:0;return c}
async function setupEditorPlan(){if(!editorClips.length){$('videoStatus').textContent='Add media to begin.';return}await Promise.all(editorClips.map(probeClip));const total=+$('videoLength').value||12,style=$('videoCutStyle').value;let weights=editorClips.map((_,i)=>style==='Fast reveal'&&i===0?1.7:style==='Detail showcase'&&i>0?1.25:1),sum=weights.reduce((a,b)=>a+b,0),cursor=0;editorPlan=editorClips.map((c,i)=>{let dur=Math.max(.7,total*weights[i]/sum);if(c.type==='video'&&c.sourceDuration)dur=Math.min(dur,c.sourceDuration);const x={...c,start:cursor,end:cursor+dur,duration:dur};cursor+=dur;return x});normalizeTimeline();renderTimeline();previewTime=0;await drawEditorFrame(0);const first=editorPlan[0];$('editorAdvice').textContent=first?.type==='image'?'Strong start: your first frame is a clean artwork reveal. Keep the hook under eight words.':'Consider using a finished artwork image as clip one so viewers understand the payoff immediately.';$('videoStatus').textContent=`Ignatz created a ${editorPlan.at(-1).end.toFixed(1)}-second ${style.toLowerCase()} using ${editorPlan.length} clip${editorPlan.length===1?'':'s'}.`;}
$('videoSetup').onclick=setupEditorPlan;
function normalizeTimeline(){let t=0;editorPlan.forEach(x=>{x.duration=Math.max(.5,+x.duration||1);x.start=t;x.end=t+x.duration;t=x.end})}
function moveClip(i,dir){const j=i+dir;if(j<0||j>=editorPlan.length)return;[editorPlan[i],editorPlan[j]]=[editorPlan[j],editorPlan[i]];editorClips=[...editorPlan];normalizeTimeline();renderTimeline();drawEditorFrame(previewTime)}
function renderTimeline(){$('clipTimeline').innerHTML=editorPlan.length?editorPlan.map((c,i)=>`<div class="clip-row"><${c.type==='image'?'img':'video'} class="clip-thumb" src="${c.url}" ${c.type==='video'?'muted':''}></${c.type==='image'?'img':'video'}><div><b>Clip ${i+1}</b><div class="small muted">${c.type} • ${c.start.toFixed(1)}–${c.end.toFixed(1)}s</div>${c.type==='video'?`<div class="trim-grid"><input class="field clipTrim" data-i="${i}" type="number" min="0" step=".25" value="${(+c.trimStart||0).toFixed(2)}" title="Video start trim"><span class="small muted">start trim</span></div>`:''}</div><input class="field clipDuration" data-i="${i}" type="number" min=".5" step=".5" value="${c.duration.toFixed(1)}" title="Clip duration"><div class="clip-controls"><button class="btn ghost clipUp" data-i="${i}" title="Move up">↑</button><button class="btn ghost clipDown" data-i="${i}" title="Move down">↓</button><button class="btn danger clipDelete" data-i="${i}" title="Remove">×</button></div></div>`).join(''):'<div class="empty">Add media to begin.</div>';document.querySelectorAll('.clipDuration').forEach(el=>el.onchange=()=>{const c=editorPlan[+el.dataset.i];c.duration=Math.max(.5,+el.value||1);if(c.type==='video'&&c.sourceDuration)c.duration=Math.min(c.duration,Math.max(.5,c.sourceDuration-(+c.trimStart||0)));normalizeTimeline();renderTimeline()});document.querySelectorAll('.clipTrim').forEach(el=>el.onchange=()=>{const c=editorPlan[+el.dataset.i];c.trimStart=Math.max(0,Math.min(+el.value||0,Math.max(0,(c.sourceDuration||0)-.5)));renderTimeline()});document.querySelectorAll('.clipDelete').forEach(b=>b.onclick=()=>{const i=+b.dataset.i;URL.revokeObjectURL(editorPlan[i].url);editorPlan.splice(i,1);editorClips=[...editorPlan];normalizeTimeline();renderTimeline();drawEditorFrame(0)});document.querySelectorAll('.clipUp').forEach(b=>b.onclick=()=>moveClip(+b.dataset.i,-1));document.querySelectorAll('.clipDown').forEach(b=>b.onclick=()=>moveClip(+b.dataset.i,1))}
async function mediaForClip(c){if(c.type==='image'){const img=new Image();img.src=c.url;await img.decode();return img}const v=document.createElement('video');v.src=c.url;v.muted=true;v.playsInline=true;v.preload='auto';await new Promise((res,rej)=>{v.onloadeddata=res;v.onerror=rej});return v}
function drawMedia(ctx,media,w,h,mode='cover'){const mw=media.videoWidth||media.naturalWidth,mh=media.videoHeight||media.naturalHeight;if(!mw||!mh)return;const sc=mode==='contain'?Math.min(w/mw,h/mh):Math.max(w/mw,h/mh),dw=mw*sc,dh=mh*sc;ctx.drawImage(media,(w-dw)/2,(h-dh)/2,dw,dh)}
function overlayText(ctx,text,y,size=38){if(!text)return;ctx.font=`800 ${size}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';const max=470,words=text.split(' '),lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>max&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);lines.slice(0,3).forEach((ln,i)=>{const yy=y+i*(size+8);ctx.lineWidth=12;ctx.strokeStyle='rgba(0,0,0,.78)';ctx.strokeText(ln,270,yy);ctx.fillStyle='#fff';ctx.fillText(ln,270,yy)})}
function drawSafeZones(ctx){ctx.save();ctx.strokeStyle='rgba(255,255,255,.55)';ctx.setLineDash([12,10]);ctx.lineWidth=3;ctx.strokeRect(28,70,430,760);ctx.fillStyle='rgba(255,255,255,.7)';ctx.font='600 18px system-ui';ctx.fillText('Keep text inside',36,62);ctx.restore()}
async function drawEditorFrame(time){const canvas=$('videoCanvas'),ctx=canvas.getContext('2d');ctx.fillStyle='#111';ctx.fillRect(0,0,canvas.width,canvas.height);if(!editorPlan.length)return;const total=editorPlan.at(-1)?.end||12;time=Math.max(0,Math.min(time,total-.01));previewTime=time;const c=editorPlan.find(x=>time>=x.start&&time<x.end)||editorPlan.at(-1);if(c){const m=await mediaForClip(c);if(c.type==='video'){m.currentTime=Math.min(Math.max(0,(c.trimStart||0)+time-c.start),Math.max(0,(m.duration||1)-.05));await new Promise(r=>{m.onseeked=r;setTimeout(r,120)})}drawMedia(ctx,m,canvas.width,canvas.height,$('videoCrop').value)}ctx.fillStyle='rgba(0,0,0,.12)';ctx.fillRect(0,0,canvas.width,canvas.height);const pos=$('videoTextPosition').value,hookY=pos==='center'?390:pos==='top'?100:125,ctaY=pos==='center'?600:pos==='top'?230:785;if(time<Math.min(2,total*.2))overlayText(ctx,$('videoHook').value.trim(),hookY,38);if(time>total-2.5)overlayText(ctx,$('videoCTA').value.trim(),ctaY,34);if($('showSafeZones').checked)drawSafeZones(ctx)}
function stopPreview(msg='Preview paused.'){clearInterval(previewTimer);previewPaused=true;$('videoStatus').textContent=msg}
$('videoPreviewBtn').onclick=async()=>{if(!editorPlan.length)return alert('Add media and let Ignatz set it up first.');clearInterval(previewTimer);previewPaused=false;let total=editorPlan.at(-1).end,t=previewTime>=total-.2?0:previewTime;$('videoStatus').textContent='Previewing…';previewTimer=setInterval(async()=>{if(previewPaused)return;await drawEditorFrame(t);t+=.12;$('renderProgress').style.width=`${Math.min(100,t/total*100)}%`;if(t>=total){clearInterval(previewTimer);previewTime=0;$('renderProgress').style.width='0%';$('videoStatus').textContent='Preview complete.'}},120)};
$('videoPauseBtn').onclick=()=>stopPreview();$('videoRestartBtn').onclick=()=>{stopPreview('Preview reset.');previewTime=0;$('renderProgress').style.width='0%';drawEditorFrame(0)};$('previewFrameBack').onclick=()=>drawEditorFrame(previewTime-.5);$('previewFrameForward').onclick=()=>drawEditorFrame(previewTime+.5);['videoCrop','videoTextPosition','showSafeZones','videoHook','videoCTA'].forEach(id=>$(id).addEventListener('input',()=>drawEditorFrame(previewTime)));
$('downloadPostPack').onclick=()=>{const subject=$('growthSubject').value.trim()||'Untitled post',hook=$('videoHook').value.trim(),cta=$('videoCTA').value.trim(),caption=$('packageCaption').textContent.trim();const text=`IGNATZ POSTING PACK\n\nPOST: ${subject}\nHOOK / COVER: ${hook}\nCTA: ${cta}\n\nCAPTION:\n${caption}\n\nFINAL CHECK:\n- Add a licensed sound inside TikTok\n- Check text stays clear of interface buttons\n- Choose a readable cover\n- Add accurate captions or alt text\n- Reply genuinely to early comments\n`;const blob=new Blob([text],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ignatz-posting-pack-${Date.now()}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)};
$('videoExport').onclick=async()=>{if(!editorPlan.length)return alert('Add media and let Ignatz set it up first.');stopPreview('Preparing export…');const canvas=$('videoCanvas'),stream=canvas.captureStream(30);let mime=['video/mp4;codecs=h264','video/webm;codecs=vp9','video/webm'].find(x=>MediaRecorder.isTypeSupported(x))||'';const rec=new MediaRecorder(stream,mime?{mimeType:mime}:undefined),chunks=[];rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);rec.onstop=()=>{const blob=new Blob(chunks,{type:mime||'video/webm'}),a=document.createElement('a'),ext=(mime||'').includes('mp4')?'mp4':'webm';a.href=URL.createObjectURL(blob);a.download=`ignatz-ready-post-${Date.now()}.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);$('renderProgress').style.width='100%';$('videoStatus').textContent=`Export complete (${ext.toUpperCase()}). Add a licensed sound in TikTok before posting.`;setTimeout(()=>$('renderProgress').style.width='0%',1800)};rec.start(250);const total=editorPlan.at(-1).end,start=performance.now();$('videoStatus').textContent='Rendering locally—keep this tab open.';async function frame(now){const t=(now-start)/1000;$('renderProgress').style.width=`${Math.min(100,t/total*100)}%`;await drawEditorFrame(Math.min(t,total-.01));if(t<total)requestAnimationFrame(frame);else setTimeout(()=>rec.stop(),250)}requestAnimationFrame(frame)};
function buildSprint(){const subject=$('growthSubject').value.trim()||'one artwork',days=[['Day 1','Strong final reveal with a short curiosity hook.'],['Day 2','Sketch-to-final carousel or process cut.'],['Day 3','Funny persona reaction or relatable artist moment.'],['Day 4','Rest or reply to comments; no new masterpiece needed.'],['Day 5','Close-up details plus one character or art fact.'],['Day 6','Community question connected to '+subject+'.'],['Day 7','Soft commission, print, or portfolio follow-up.']];$('sprintBoard').innerHTML=days.map(([d,x])=>`<div class="sprint-day"><b>${d}</b><span class="small">${esc(x)}</span></div>`).join('')}
