const streamChecklistItems=['Update title, category, tags, and go-live notification','Test microphone level and remove background noise','Confirm game/art capture and camera framing','Open chat and moderation controls','Prepare water and a short break screen','Write one opening question for chat','Mark 2–3 moments you want to turn into clips'];
function ensureStreamState(){state.streamPlans=Array.isArray(state.streamPlans)?state.streamPlans:[];state.streamSessions=Array.isArray(state.streamSessions)?state.streamSessions:[];state.preferences.streamChecks=Array.isArray(state.preferences.streamChecks)?state.preferences.streamChecks:[]}
function renderStreamChecklist(){ensureStreamState();$('streamChecklist').innerHTML=streamChecklistItems.map((x,i)=>`<label class="stream-check"><input type="checkbox" data-streamcheck="${i}" ${state.preferences.streamChecks.includes(i)?'checked':''}><span>${esc(x)}</span></label>`).join('');document.querySelectorAll('[data-streamcheck]').forEach(x=>x.onchange=()=>{const i=+x.dataset.streamcheck;state.preferences.streamChecks=x.checked?[...new Set([...state.preferences.streamChecks,i])]:state.preferences.streamChecks.filter(n=>n!==i);save()})}
function buildStreamPlan(){ensureStreamState();const game=$('streamGame').value.trim()||'a creative variety stream',goal=$('streamGoal').value,mins=+$('streamLength').value||90,energy=$('streamEnergy').value,angle=$('streamAngle').value.trim()||'a clear challenge and regular chat check-ins';const titleOptions=[`${game}: ${angle}`,`${energy.split(' ')[0]} ${game} — chat chooses what happens`,`${game} but every mistake changes the challenge`];const start=8,end=8,core=Math.max(30,mins-start-end),segments=[['0–8 min','Starting soon, greet early viewers, explain today’s goal, and ask one easy chat question.'],[`8–${8+Math.round(core*.4)} min`,`Main ${game} segment. Re-state the challenge for new arrivals and mark one clip-worthy moment.`],[`${8+Math.round(core*.4)}–${8+Math.round(core*.75)} min`,'Change the pace: viewer choice, mini-challenge, Q&A, or behind-the-scenes explanation.'],[`${8+Math.round(core*.75)}–${mins-8} min`,'Final push with a clear win condition. Mention the next stream naturally.'],[`${mins-8}–${mins} min`,'Recap the best moment, thank specific chat participation, and raid a compatible creator when appropriate.']];const prompts=['What are you working on or playing lately?','Should I choose the safe option or the chaotic option?','What moment from today deserves a clip?','What should return in the next stream?'];const clipMoments=['First clear payoff or reveal','Biggest mistake or funniest reaction','One helpful explanation under 45 seconds','Chat choosing the next action'];$('overlayTitle').textContent=titleOptions[0];$('streamSavedTitle').value=titleOptions[0];$('streamPlanOutput').innerHTML=`<div class="promo-section stream-plan-card"><h3>Title options</h3>${titleOptions.map(x=>`<button class="stream-tag stream-title-choice" type="button">${esc(x)}</button>`).join('')}<button class="btn ghost copy-stream-plan" type="button">Copy full plan</button></div><div class="promo-section"><h3>Run of show</h3><div class="stream-segments">${segments.map(x=>`<div class="stream-segment"><b>${x[0]}</b><span>${esc(x[1])}</span></div>`).join('')}</div></div><div class="promo-section"><h3>Conversation prompts</h3>${prompts.map(x=>`<div class="stream-check">💬 <span>${esc(x)}</span></div>`).join('')}</div><div class="promo-section"><h3>Clip targets</h3>${clipMoments.map(x=>`<div class="stream-check">✂️ <span>${esc(x)}</span></div>`).join('')}</div><div class="notice"><b>Ignatz’s focus:</b> ${esc(goal)}. Do not fill every quiet second. Ask a clear question, wait, then respond to people by name when possible.</div>`;document.querySelectorAll('.stream-title-choice').forEach(button=>button.addEventListener('click',()=>{$('streamSavedTitle').value=button.textContent;$('overlayTitle').textContent=button.textContent;document.querySelectorAll('.stream-title-choice').forEach(x=>x.classList.toggle('selected',x===button))}));document.querySelector('.copy-stream-plan')?.addEventListener('click',async e=>{const text=$('streamPlanOutput').innerText;try{await navigator.clipboard.writeText(text);e.currentTarget.textContent='Copied!';setTimeout(()=>e.currentTarget.textContent='Copy full plan',1200)}catch{alert('Copy is unavailable here. Select the generated text and copy it manually.')}})}
function renderStreaming(){ensureStreamState();renderStreamChecklist();$('savedStreams').innerHTML=state.streamPlans.length?state.streamPlans.map(x=>`<div class="item stream-plan-card"><div class="item-head"><div><strong>${esc(x.title)}</strong><div class="small muted">${esc(x.date||'Unscheduled')} ${esc(x.time||'')} • ${esc(x.game||'Variety')}</div></div><button class="btn danger deleteStream" data-id="${x.id}">×</button></div></div>`).join(''):'<div class="empty">No upcoming streams saved.</div>';document.querySelectorAll('.deleteStream').forEach(b=>b.onclick=()=>{state.streamPlans=state.streamPlans.filter(x=>String(x.id)!==b.dataset.id);save()});const a=state.streamSessions;if(a.length){const avg=k=>Math.round(a.reduce((s,x)=>s+(+x[k]||0),0)/a.length);$('streamStats').innerHTML=`<div class="stream-stat"><span class="small muted">Sessions</span><strong>${a.length}</strong></div><div class="stream-stat"><span class="small muted">Avg viewers</span><strong>${avg('avgViewers')}</strong></div><div class="stream-stat"><span class="small muted">Avg chatters</span><strong>${avg('chatters')}</strong></div><div class="stream-stat"><span class="small muted">Followers/session</span><strong>${avg('followers')}</strong></div>`;$('streamCoach').textContent=avg('chatters')>=Math.max(2,avg('avgViewers')*.25)?'Your chat participation is healthy relative to your audience size. Keep using direct questions and recurring segments.':'Prioritize interaction over longer hours: greet arrivals, ask one-answer questions, and create a repeatable viewer-choice segment.'}else $('streamStats').innerHTML=''}
function runStreamGenerator(trigger){try{const btn=trigger||$('buildStreamPlan');const original=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='Building your stream…'}buildStreamPlan();$('streamPlanOutput').scrollIntoView({behavior:'smooth',block:'nearest'});if(btn){setTimeout(()=>{btn.disabled=false;btn.textContent=original},450)}}catch(error){console.error('Twitch generator failed',error);$('streamPlanOutput').innerHTML='<div class="notice"><b>Ignatz could not build the plan.</b><br>Please refresh the app once. Your saved data is safe.</div>';if(trigger)trigger.disabled=false}}
$('buildStreamPlan').addEventListener('click',e=>runStreamGenerator(e.currentTarget));$('streamQuickPlan').addEventListener('click',e=>{if(!$('streamGame').value)$('streamGame').value='art and community hangout';runStreamGenerator(e.currentTarget)});$('streamHeroGenerate').addEventListener('click',e=>{openView('streaming');runStreamGenerator(e.currentTarget)});$('streamHeroChecklist').addEventListener('click',()=>{$('streamChecklist').scrollIntoView({behavior:'smooth',block:'center'})});
$('overlayAccent').onchange=()=>{document.querySelector('.stream-overlay-preview').style.borderColor=$('overlayAccent').value;document.querySelector('.cam-box').style.borderColor=$('overlayAccent').value};
$('resetStreamChecklist').onclick=()=>{state.preferences.streamChecks=[];save()};
$('saveStreamPlan').onclick=()=>{ensureStreamState();const title=$('streamSavedTitle').value.trim();if(!title)return alert('Add a working stream title.');state.streamPlans.unshift({id:Date.now(),title,date:$('streamDate').value,time:$('streamTime').value,game:$('streamGame').value.trim()||'Variety'});save()};
$('buildStreamClips').onclick=()=>{const moment=$('streamMoment').value.trim();if(!moment)return alert('Describe the moment or add a timestamp.');const type=$('streamMomentType').value,platform=$('streamClipPlatform').value;const hooks={"Funny fail or reaction":'I knew this was going badly before it happened…',"Impressive play":'This is the cleanest moment from the entire stream.',"Helpful tip":'This one change made the next attempt much easier.',"Chat interaction":'Chat made the decision—and immediately regretted it.',"Story or opinion":'I did not expect this conversation during stream.',"Art reveal":'We finished this live, and the final detail changed everything.'};$('streamClipOutput').innerHTML=`<div class="promo-section"><h3>Hook</h3><p><b>${esc(hooks[type])}</b></p></div><div class="promo-section"><h3>Cut plan</h3><div class="stream-segment"><b>0–1s</b><span>Open on the reaction, result, or strongest frame.</span></div><div class="stream-segment"><b>1–4s</b><span>Give only the context needed to understand the moment.</span></div><div class="stream-segment"><b>4–12s</b><span>${esc(moment)}</span></div><div class="stream-segment"><b>Final 2s</b><span>End immediately after the payoff; do not explain the joke twice.</span></div></div><div class="promo-section"><h3>Caption for ${esc(platform)}</h3><p>${esc(type)} from stream. Live moments are always less predictable than planned content. What would you have done here?</p></div>`};
$('logStreamSession').onclick=()=>{ensureStreamState();state.streamSessions.unshift({id:Date.now(),date:today(),avgViewers:+$('streamAvgViewers').value||0,peakViewers:+$('streamPeakViewers').value||0,followers:+$('streamFollowers').value||0,chatters:+$('streamChatters').value||0,game:$('streamGame').value.trim()});save()};
// Keep browser UI colors synchronized and surface a theme test in Settings.
function syncThemeChrome(){const night=document.body.classList.contains('night');document.querySelector('meta[name="theme-color"]')?.setAttribute('content',night?'#232132':'#fff7f1')}
$('nightToggle').addEventListener('click',()=>setTimeout(syncThemeChrome,0));syncThemeChrome();
const themeAudit=document.createElement('div');themeAudit.className='theme-audit';themeAudit.innerHTML='<b>Theme contrast repaired</b><span class="small muted">Cards, forms, badges, generated results, calendars, and Twitch tools now use shared light/dark surfaces.</span><button class="btn ghost" type="button" id="themeTest">Test theme</button>';if($('settings'))$('settings').prepend(themeAudit);$('themeTest').onclick=()=>$('nightToggle').click();
renderStreaming();
window.addEventListener('error',event=>{console.error(event.error||event.message);const active=document.querySelector('.view.active');if(active&&active.id==='streaming'&&!document.querySelector('.runtime-warning')){const warning=document.createElement('div');warning.className='runtime-warning notice';warning.innerHTML='<b>A tool hit an unexpected error.</b> Refresh once and try again. Your saved studio data remains on this device.';active.prepend(warning)}});

